"use client";

/* eslint-disable @next/next/no-img-element -- Private Supabase signed URLs are short-lived and not configured as stable Next Image remotes. */

import Link from "next/link";
import { useActionState, useState, useTransition } from "react";
import { addRepairPart, addTimeEntry, confirmQualityAndComplete, markReadyForCollection, reportRepairDelay, saveExecutionDiagnosis, saveInspectionItem, saveRepairChecklistItem, saveTestingItem, saveWarrantyRecord, sendQuotation, startDiagnosis, updateRepairProgress, type TechnicianWorkflowState } from "@/lib/repairs/technician-actions";
import { MessageForm } from "@/components/repairs/technician-workflow-forms";
import { Icon, type IconName } from "@/components/ui/icon";

export type ExecutionRepair = {
  id: string; reference: string; status: string; device_category: string; brand: string; model: string; approximate_age: string | null; warranty_status: string | null; purchase_date: string | null; problem_title: string; problem_description: string; symptoms: string; urgency: string; province: string; city: string; area: string; service_preference: string; submitted_at: string; updated_at: string; assigned_at: string | null; repair_started_at: string | null; completed_at: string | null;
  customer: { full_name: string | null; display_name: string | null; phone: string | null; city: string | null } | null;
  technician: { full_name: string | null; display_name: string | null } | null;
};
export type ExecutionDiagnosis = { id: string; summary: string; observed_faults: string; likely_cause: string | null; confirmed_cause: string | null; repair_recommendation: string | null; required_parts: string | null; estimated_duration: string | null; complexity: string; priority: string; public_notes: string | null; private_notes: string | null; submitted_at: string | null; created_at: string };
export type ExecutionItem = { id: string; item_key: string; label: string; result?: string; completed?: boolean; notes: string | null; checked_at?: string | null; tested_at?: string | null; completed_at?: string | null };
export type ExecutionPart = { id: string; part_name: string; manufacturer?: string | null; part_number: string | null; quantity: number; condition: string; supplier: string | null; warranty_note: string | null; unit_cost_amount?: number | null; cost_amount: number | null; currency: string; availability?: string | null; notes?: string | null; installed_at: string | null; created_at: string };
export type ExecutionPhoto = { id: string; phase: string | null; caption: string | null; file_name: string; content_type: string | null; signedUrl: string | null; created_at: string };
export type ExecutionTime = { id: string; category: string; minutes: number; notes: string | null; created_at: string };
export type ExecutionWarranty = { id: string; warranty_provided: boolean; duration: string | null; coverage: string | null; terms: string | null; serial_numbers: string | null; warranty_reference: string | null; updated_at: string } | null;
export type ExecutionQuote = { id: string; version: number; status: string; labour_amount?: number | null; parts_amount?: number | null; service_fee_amount?: number | null; additional_fees_amount?: number | null; discount_amount?: number | null; tax_amount?: number | null; total_amount: number | null; currency: string; notes?: string | null; estimated_completion_at?: string | null; warranty_note: string | null; revision_reason?: string | null; approved_at: string | null; declined_at?: string | null; clarification_requested_at?: string | null; clarification_message?: string | null; created_at: string; lineItems?: ExecutionQuoteLineItem[] };
export type ExecutionQuoteLineItem = { id: string; quote_id: string; item_type: string; description: string; quantity: number; unit_amount: number; total_amount: number; customer_visible?: boolean | null };
export type ExecutionEvent = { id: string; status: string; title: string; description: string | null; responsible_party: string; created_at: string };
export type ExecutionConfirmation = { id: string; confirmation_text: string; confirmed_at: string };
export type ExecutionMessage = { id: string; sender_role: string; message: string; read_at: string | null; created_at: string };
export type ExecutionNotification = { id: string; type: string; title: string; message: string | null; read_at: string | null; created_at: string };
export type ExecutionReadiness = { repair_complete: boolean; testing_passed: boolean; photos_uploaded: boolean; summary_generated: boolean; warranty_recorded: boolean; customer_notified: boolean; ready_marked_at: string | null } | null;

export type RepairExecutionData = { repair: ExecutionRepair; diagnosis: ExecutionDiagnosis | null; inspections: ExecutionItem[]; checklist: ExecutionItem[]; tests: ExecutionItem[]; parts: ExecutionPart[]; photos: ExecutionPhoto[]; timeEntries: ExecutionTime[]; warranty: ExecutionWarranty; quotes: ExecutionQuote[]; events: ExecutionEvent[]; confirmations: ExecutionConfirmation[]; messages: ExecutionMessage[]; notifications: ExecutionNotification[]; readiness: ExecutionReadiness };

const initial: TechnicianWorkflowState = { ok: false };
const inspectionDefaults = ["physical_damage", "liquid_damage", "power", "battery", "display", "keyboard", "ports", "camera", "speakers", "microphone", "wifi", "bluetooth", "storage", "memory", "motherboard", "accessories_received"];
const checklistDefaults = ["device_inspected", "diagnosis_completed", "customer_approved", "parts_installed", "firmware_updated", "device_cleaned", "stress_tested", "quality_checked", "customer_notified"];
const testingDefaults = ["powers_on", "display_working", "charging_working", "keyboard_functional", "touchscreen_functional", "wifi_connected", "bluetooth_working", "audio_verified", "camera_verified", "thermals_acceptable", "performance_acceptable", "battery_health_acceptable"];
const labels: Record<string, string> = Object.fromEntries([...inspectionDefaults, ...checklistDefaults, ...testingDefaults].map((key) => [key, label(key)]));

export function RepairExecutionWorkspace({ data }: { data: RepairExecutionData }) {
  const [openMobile, setOpenMobile] = useState("diagnosis");
  const totals = labourTotals(data.timeEntries);
  const completion = completionReadiness(data);
  return <div className="mt-6 grid gap-6">
    <StatusBanner data={data} totals={totals} completion={completion} />
    <MobileAccordions open={openMobile} setOpen={setOpenMobile} data={data} totals={totals} completion={completion} />
    <div className="hidden gap-6 md:grid xl:grid-cols-[minmax(0,0.65fr)_minmax(320px,0.35fr)]">
      <main className="grid min-w-0 content-start gap-5"><QuotationBuilder reference={data.repair.reference} diagnosis={data.diagnosis} quotes={data.quotes} parts={data.parts} /><RepairProgress reference={data.repair.reference} events={data.events} current={data.repair.status} /><MessageCenter reference={data.repair.reference} messages={data.messages} diagnosis={data.diagnosis} /><CustomerTimeline events={data.events} current={data.repair.status} /><DiagnosisEditor reference={data.repair.reference} diagnosis={data.diagnosis} /><InspectionChecklist reference={data.repair.reference} items={data.inspections} /><RepairGallery photos={data.photos} /><TimeTracking reference={data.repair.reference} entries={data.timeEntries} totals={totals} /><TestingChecklist reference={data.repair.reference} items={data.tests} /><RepairSummary data={data} totals={totals} /><AuditLog events={data.events} quotes={data.quotes} messages={data.messages} /></main>
      <aside className="grid content-start gap-5 xl:sticky xl:top-24 xl:max-h-[calc(100vh-7rem)] xl:overflow-y-auto"><CustomerPanel repair={data.repair} /><PartsTable reference={data.repair.reference} parts={data.parts} /><NotificationPanel notifications={data.notifications} /><ApprovalHistory quotes={data.quotes} /><WarrantyCard reference={data.repair.reference} warranty={data.warranty} quotes={data.quotes} /><RepairChecklist reference={data.repair.reference} items={data.checklist} /><CollectionReadiness reference={data.repair.reference} completion={completion} readiness={data.readiness} /><CompletionWizard reference={data.repair.reference} completion={completion} confirmations={data.confirmations} /><DeviceSummary repair={data.repair} /></aside>
    </div>
    <div className="fixed inset-x-0 bottom-0 z-20 border-t border-[var(--divider)] bg-white/95 p-3 shadow-[0_-10px_30px_rgba(11,18,32,0.08)] backdrop-blur md:hidden"><div className="grid grid-cols-2 gap-2"><Link href="/technician/jobs" className="inline-flex min-h-12 items-center justify-center rounded-[14px] bg-[var(--secondary-surface)] text-sm font-bold text-[var(--deep-navy)]">Back</Link><a href="#completion" className="inline-flex min-h-12 items-center justify-center rounded-[14px] bg-[var(--brand-blue)] text-sm font-bold text-white">Complete</a></div></div>
  </div>;
}

export function RepairExecutionHeader({ repair }: { repair: ExecutionRepair }) {
  return <header className="rounded-[32px] bg-white p-6 shadow-[var(--shadow-soft)] sm:p-8"><div className="flex flex-wrap items-start justify-between gap-5"><div><p className="text-sm font-black uppercase tracking-[0.18em] text-[var(--brand-blue)]">Diagnosis workspace</p><h1 className="mt-3 text-3xl font-bold tracking-[-0.04em] text-[var(--deep-navy)] sm:text-5xl">{repair.reference}</h1><p className="mt-3 text-lg leading-8 text-[var(--secondary-text)]">{repair.brand} {repair.model} · {repair.device_category}</p></div><div className="flex flex-wrap gap-2"><Link href="/technician/jobs" className="inline-flex min-h-11 items-center rounded-[14px] bg-[var(--secondary-surface)] px-4 text-sm font-bold text-[var(--deep-navy)]">Back</Link><a href="#timeline" className="inline-flex min-h-11 items-center rounded-[14px] bg-white px-4 text-sm font-bold text-[var(--brand-blue)] ring-1 ring-[var(--divider)]">Open Timeline</a><a href="#messages" className="inline-flex min-h-11 items-center rounded-[14px] bg-[var(--brand-blue)] px-4 text-sm font-bold text-white">Message Customer</a></div></div><dl className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><Metric label="Customer" value={repair.customer?.display_name || repair.customer?.full_name || "Not available"} /><Metric label="Status" value={label(repair.status)} /><Metric label="Priority" value={label(repair.urgency)} /><Metric label="Technician" value={repair.technician?.display_name || repair.technician?.full_name || "Not available"} /><Metric label="Submitted" value={dateTime(repair.submitted_at)} /></dl></header>;
}

function StatusBanner({ data, totals, completion }: { data: RepairExecutionData; totals: ReturnType<typeof labourTotals>; completion: ReturnType<typeof completionReadiness> }) { return <section className="rounded-[28px] bg-[var(--deep-navy)] p-5 text-white shadow-[var(--shadow-soft)] sm:p-6"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-sm font-bold uppercase tracking-[0.16em] text-blue-100">Current workflow</p><h2 className="mt-2 text-2xl font-bold">{label(data.repair.status)}</h2><p className="mt-2 max-w-3xl text-sm leading-6 text-blue-50">Every status change is timestamped through the repair timeline. Completion requires diagnosis, inspection, testing, warranty, evidence and quality confirmation.</p></div><StartDiagnosisButton reference={data.repair.reference} status={data.repair.status} /></div><div className="mt-5 grid gap-3 sm:grid-cols-4"><DarkMetric label="Labour" value={`${totals.total} min`} /><DarkMetric label="Photos" value={`${data.photos.length}`} /><DarkMetric label="Testing passed" value={`${completion.testingPassed ? "Yes" : "No"}`} /><DarkMetric label="Ready" value={`${completion.readyCount}/${completion.requiredCount}`} /></div></section>; }

function StartDiagnosisButton({ reference, status }: { reference: string; status: string }) { const [pending, start] = useTransition(); const [message, setMessage] = useState(""); if (!["accepted", "technician_assigned"].includes(status)) return null; return <button type="button" disabled={pending} onClick={() => start(async () => { const result = await startDiagnosis(reference); setMessage(result.message || ""); })} className="min-h-12 rounded-[14px] bg-white px-5 text-sm font-bold text-[var(--deep-navy)] disabled:opacity-60">{pending ? "Starting..." : message || "Begin Diagnosis"}</button>; }
function MobileAccordions({ open, setOpen, data, completion }: { open: string; setOpen(v: string): void; data: RepairExecutionData; totals: ReturnType<typeof labourTotals>; completion: ReturnType<typeof completionReadiness> }) { const sections = [["quotation", <QuotationBuilder key="q" reference={data.repair.reference} diagnosis={data.diagnosis} quotes={data.quotes} parts={data.parts} />], ["progress", <RepairProgress key="rp" reference={data.repair.reference} events={data.events} current={data.repair.status} />], ["messages", <MessageCenter key="m" reference={data.repair.reference} messages={data.messages} diagnosis={data.diagnosis} />], ["parts", <PartsTable key="p" reference={data.repair.reference} parts={data.parts} />], ["timeline", <CustomerTimeline key="ct" events={data.events} current={data.repair.status} />], ["diagnosis", <DiagnosisEditor key="d" reference={data.repair.reference} diagnosis={data.diagnosis} />], ["inspection", <InspectionChecklist key="i" reference={data.repair.reference} items={data.inspections} />], ["photos", <RepairGallery key="g" photos={data.photos} />], ["testing", <TestingChecklist key="t" reference={data.repair.reference} items={data.tests} />], ["collection", <CollectionReadiness key="cr" reference={data.repair.reference} completion={completion} readiness={data.readiness} />], ["completion", <CompletionWizard key="c" reference={data.repair.reference} completion={completion} confirmations={data.confirmations} />]] as const; return <div className="grid gap-3 md:hidden">{sections.map(([key, node]) => <section key={key} className="rounded-2xl bg-white shadow-[var(--shadow-soft)]"><button type="button" onClick={() => setOpen(open === key ? "" : key)} className="flex min-h-14 w-full items-center justify-between px-4 text-left font-bold capitalize text-[var(--deep-navy)]">{key}<span>{open === key ? "−" : "+"}</span></button>{open === key ? <div className="border-t border-[var(--divider)] p-3">{node}</div> : null}</section>)}</div>; }

function DiagnosisEditor({ reference, diagnosis }: { reference: string; diagnosis: ExecutionDiagnosis | null }) { const [state, action, pending] = useActionState(saveExecutionDiagnosis, initial); return <Card id="diagnosis" title="Diagnosis" eyebrow="Auto-save ready documentation" icon="search"><form action={action} className="grid gap-4"><input type="hidden" name="reference" value={reference} /><input type="hidden" name="diagnosisId" value={diagnosis?.id || ""} /><AutosaveIndicator pending={pending} state={state} /><Field name="summary" label="Observed issues" defaultValue={diagnosis?.summary} textarea required /><Field name="observedFaults" label="Fault description" defaultValue={diagnosis?.observed_faults} textarea required /><div className="grid gap-4 lg:grid-cols-2"><Field name="likelyCause" label="Likely cause" defaultValue={diagnosis?.likely_cause} textarea /><Field name="confirmedCause" label="Confirmed cause" defaultValue={diagnosis?.confirmed_cause} textarea /></div><Field name="repairRecommendation" label="Repair recommendation" defaultValue={diagnosis?.repair_recommendation} textarea /><Field name="requiredParts" label="Suggested replacement parts" defaultValue={diagnosis?.required_parts} /><div className="grid gap-4 sm:grid-cols-3"><Field name="estimatedDuration" label="Estimated repair time" defaultValue={diagnosis?.estimated_duration} /><Select name="complexity" label="Difficulty" defaultValue={diagnosis?.complexity || "moderate"} options={["simple", "moderate", "complex", "specialist"]} /><Select name="priority" label="Priority" defaultValue={diagnosis?.priority || "normal"} options={["low", "normal", "urgent", "safety"]} /></div><Field name="publicNotes" label="Customer-visible notes" defaultValue={diagnosis?.public_notes} textarea /><Field name="privateNotes" label="Internal technician notes" defaultValue={diagnosis?.private_notes} textarea /><AIReadyPanel /><button disabled={pending} className="min-h-12 rounded-[14px] bg-[var(--brand-blue)] px-5 text-sm font-bold text-white disabled:opacity-60">{pending ? "Saving..." : "Save Diagnosis"}</button></form></Card>; }
function AIReadyPanel() { return <div className="rounded-2xl border border-dashed border-blue-200 bg-[var(--blue-surface)] p-4"><p className="text-sm font-bold text-[var(--brand-blue)]">AI-ready diagnosis hooks</p><div className="mt-3 grid gap-2 text-sm text-[var(--secondary-text)] sm:grid-cols-2"><span>Suggest possible causes</span><span>Recommend diagnostic tests</span><span>Suggest replacement parts</span><span>Highlight common failures</span></div><p className="mt-3 text-xs text-[var(--muted-text)]">Integration placeholder only. No AI logic is executed.</p></div>; }

function InspectionChecklist({ reference, items }: { reference: string; items: ExecutionItem[] }) { return <ChecklistCard title="Device inspection" eyebrow="Pass / fail / not tested" defaults={inspectionDefaults} items={items} reference={reference} action={saveInspectionItem} type="inspection" />; }
function RepairChecklist({ reference, items }: { reference: string; items: ExecutionItem[] }) { return <ChecklistCard title="Repair checklist" eyebrow="Timestamped completion" defaults={checklistDefaults} items={items} reference={reference} action={saveRepairChecklistItem} type="repair" compact />; }
function TestingChecklist({ reference, items }: { reference: string; items: ExecutionItem[] }) { return <ChecklistCard title="Testing workspace" eyebrow="Quality assurance" defaults={testingDefaults} items={items} reference={reference} action={saveTestingItem} type="testing" />; }
function ChecklistCard({ title, eyebrow, defaults, items, reference, action, type, compact = false }: { title: string; eyebrow: string; defaults: string[]; items: ExecutionItem[]; reference: string; action: (previous: TechnicianWorkflowState, formData: FormData) => Promise<TechnicianWorkflowState>; type: "inspection" | "repair" | "testing"; compact?: boolean }) { const byKey = new Map(items.map((item) => [item.item_key, item])); return <Card id={type} title={title} eyebrow={eyebrow} icon="check"><div className={`grid gap-3 ${compact ? "" : "lg:grid-cols-2"}`}>{defaults.map((key) => <ChecklistItem key={key} reference={reference} itemKey={key} item={byKey.get(key)} action={action} type={type} />)}</div></Card>; }
function ChecklistItem({ reference, itemKey, item, action, type }: { reference: string; itemKey: string; item?: ExecutionItem; action: (previous: TechnicianWorkflowState, formData: FormData) => Promise<TechnicianWorkflowState>; type: "inspection" | "repair" | "testing" }) { const [state, formAction, pending] = useActionState(action, initial); return <form action={formAction} className="rounded-2xl bg-[var(--secondary-surface)] p-3"><input type="hidden" name="reference" value={reference} /><input type="hidden" name="itemKey" value={itemKey} /><div className="flex items-center justify-between gap-3"><p className="text-sm font-bold text-[var(--deep-navy)]">{labels[itemKey]}</p>{type === "repair" ? <input name="completed" type="checkbox" defaultChecked={Boolean(item?.completed)} aria-label={`Complete ${labels[itemKey]}`} className="size-5 accent-[var(--brand-blue)]" /> : <select name="result" defaultValue={item?.result || (type === "testing" ? "retest" : "not_tested")} className="min-h-10 rounded-xl border border-[var(--divider)] bg-white px-2 text-xs font-bold"><option value="pass">Pass</option><option value="fail">Fail</option><option value={type === "testing" ? "retest" : "not_tested"}>{type === "testing" ? "Retest" : "Not Tested"}</option></select>}</div><input name="notes" defaultValue={item?.notes || ""} placeholder="Optional notes" className="mt-2 min-h-10 w-full rounded-xl border border-[var(--divider)] bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-[var(--brand-blue)]" /><div className="mt-2 flex items-center justify-between gap-2"><span className="text-xs text-[var(--muted-text)]">{timestamp(item)}</span><button disabled={pending} className="min-h-9 rounded-xl bg-white px-3 text-xs font-bold text-[var(--brand-blue)] disabled:opacity-60">{pending ? "Saving" : "Save"}</button></div><Feedback state={state} /></form>; }

function PartsTable({ reference, parts }: { reference: string; parts: ExecutionPart[] }) { const [state, action, pending] = useActionState(addRepairPart, initial); return <Card id="parts" title="Parts management" eyebrow="Availability, cost and warranty" icon="device"><form action={action} className="grid gap-3 rounded-2xl bg-[var(--secondary-surface)] p-4"><input type="hidden" name="reference" value={reference} /><div className="grid gap-3 md:grid-cols-3"><Field name="partName" label="Part name" required /><Field name="manufacturer" label="Manufacturer" /><Field name="partNumber" label="Part number" /></div><div className="grid gap-3 md:grid-cols-4"><Field name="quantity" label="Quantity" defaultValue="1" type="number" /><Select name="condition" label="Condition" options={["new", "refurbished", "used"]} /><Select name="availability" label="Availability" options={["available", "ordered", "backordered", "installed", "cancelled"]} /><Field name="supplier" label="Supplier" /></div><div className="grid gap-3 md:grid-cols-3"><Field name="unitCost" label="Unit cost" type="number" /><Field name="installedAt" label="Installation date" type="datetime-local" /><Field name="warranty" label="Warranty" /></div><Field name="notes" label="Internal part notes" /><button disabled={pending} className="min-h-12 rounded-[14px] bg-[var(--deep-navy)] text-sm font-bold text-white disabled:opacity-60">Record Part</button><Feedback state={state} /></form>{parts.length ? <div className="mt-5 overflow-x-auto"><table className="w-full min-w-[860px] text-left text-sm"><caption className="sr-only">Replacement parts recorded for this repair</caption><thead className="text-xs uppercase tracking-[0.12em] text-[var(--muted-text)]"><tr><th className="py-2">Part</th><th>Manufacturer</th><th>Part #</th><th>Qty</th><th>Condition</th><th>Availability</th><th>Supplier</th><th>Unit</th><th>Total</th><th>Warranty</th></tr></thead><tbody className="divide-y divide-[var(--divider)]">{parts.map((part) => <tr key={part.id}><td className="py-3 font-bold text-[var(--deep-navy)]">{part.part_name}{part.notes ? <span className="block text-xs font-medium text-[var(--muted-text)]">{part.notes}</span> : null}</td><td>{part.manufacturer || "�"}</td><td>{part.part_number || "�"}</td><td>{part.quantity}</td><td>{label(part.condition)}</td><td><span className="rounded-full bg-[var(--blue-surface)] px-2 py-1 text-xs font-bold text-[var(--brand-blue)]">{label(part.availability || "available")}</span></td><td>{part.supplier || "�"}</td><td>{money(part.unit_cost_amount ?? null, part.currency)}</td><td>{money(part.cost_amount, part.currency)}</td><td>{part.warranty_note || "�"}</td></tr>)}</tbody></table></div> : <Empty title="No parts recorded" body="Only real replacement parts saved by a technician appear here." />}</Card>; }

function RepairGallery({ photos }: { photos: ExecutionPhoto[] }) { return <Card id="photos" title="Photo documentation" eyebrow="Before, during, completed, evidence" icon="upload"><div className="rounded-2xl border border-dashed border-[var(--divider)] bg-[var(--secondary-surface)] p-5 text-sm text-[var(--secondary-text)]"><strong className="text-[var(--deep-navy)]">Upload integration point:</strong> drag-and-drop, mobile upload, replace/delete, video evidence and progress indicators are supported by the component architecture; storage mutations are not fabricated here.</div>{photos.length ? <div className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{photos.map((photo) => <a key={photo.id} href={photo.signedUrl || "#"} target="_blank" rel="noreferrer" className="overflow-hidden rounded-2xl bg-[var(--secondary-surface)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-[var(--brand-blue)]"><div className="aspect-[4/3] bg-slate-100">{photo.signedUrl && (photo.content_type || "").startsWith("image/") ? <img src={photo.signedUrl} alt={photo.caption || photo.file_name} loading="lazy" className="size-full object-cover" /> : <div className="grid size-full place-items-center font-bold text-[var(--muted-text)]">{photo.file_name}</div>}</div><div className="p-3"><p className="text-xs font-black uppercase tracking-[0.14em] text-[var(--brand-blue)]">{label(photo.phase || "media")}</p><p className="mt-1 text-sm font-bold text-[var(--deep-navy)]">{photo.caption || photo.file_name}</p></div></a>)}</div> : <Empty title="No repair evidence uploaded" body="Before, during, completed, component and damage evidence will appear when real media exists." />}</Card>; }
function TimeTracking({ reference, entries, totals }: { reference: string; entries: ExecutionTime[]; totals: ReturnType<typeof labourTotals> }) { const [state, action, pending] = useActionState(addTimeEntry, initial); return <Card id="time" title="Time tracking" eyebrow="Labour totals" icon="network"><div className="grid gap-3 sm:grid-cols-5"><Metric label="Diagnosis" value={`${totals.diagnosis} min`} /><Metric label="Repair" value={`${totals.repair} min`} /><Metric label="Testing" value={`${totals.testing} min`} /><Metric label="Paused" value={`${totals.paused} min`} /><Metric label="Total" value={`${totals.total} min`} /></div><form action={action} className="mt-5 grid gap-3 rounded-2xl bg-[var(--secondary-surface)] p-4 sm:grid-cols-[1fr_1fr_2fr_auto]"><input type="hidden" name="reference" value={reference} /><Select name="category" label="Category" options={["diagnosis", "repair", "testing", "paused"]} /><Field name="minutes" label="Minutes" type="number" /><Field name="notes" label="Notes" /><button disabled={pending} className="self-end rounded-[14px] bg-[var(--brand-blue)] px-4 py-3 text-sm font-bold text-white disabled:opacity-60">Add</button></form><Feedback state={state} />{entries.length ? <div className="mt-4 grid gap-2">{entries.map((entry) => <p key={entry.id} className="rounded-xl bg-[var(--secondary-surface)] p-3 text-sm"><strong>{label(entry.category)}</strong> · {entry.minutes} min · {dateTime(entry.created_at)} {entry.notes ? `· ${entry.notes}` : ""}</p>)}</div> : null}</Card>; }
function ApprovalHistory({ quotes }: { quotes: ExecutionQuote[] }) { return <Card id="approval" title="Customer approval history" eyebrow="Read-only quotation trail" icon="shield">{quotes.length ? <div className="grid gap-3">{quotes.map((quote) => <article key={quote.id} className="rounded-2xl bg-[var(--secondary-surface)] p-4"><div className="flex justify-between gap-3"><p className="font-bold text-[var(--deep-navy)]">Quotation v{quote.version}</p><span className="text-sm font-bold text-[var(--brand-blue)]">{label(quote.status)}</span></div><p className="mt-2 text-sm text-[var(--secondary-text)]">Total: {money(quote.total_amount, quote.currency)} · Created: {dateTime(quote.created_at)} · Approved: {quote.approved_at ? dateTime(quote.approved_at) : "Not approved"}</p></article>)}</div> : <Empty title="No approval history" body="Approved quotation revisions and timestamps will appear here and cannot be edited." />}</Card>; }
function WarrantyCard({ reference, warranty, quotes }: { reference: string; warranty: ExecutionWarranty; quotes: ExecutionQuote[] }) { const [state, action, pending] = useActionState(saveWarrantyRecord, initial); return <Card id="warranty" title="Warranty record" eyebrow="Customer-facing clarity" icon="shield"><form action={action} className="grid gap-4"><input type="hidden" name="reference" value={reference} /><label className="flex items-center gap-3 text-sm font-bold text-[var(--deep-navy)]"><input name="warrantyProvided" type="checkbox" defaultChecked={Boolean(warranty?.warranty_provided)} className="size-5 accent-[var(--brand-blue)]" /> Warranty provided</label><div className="grid gap-3 sm:grid-cols-2"><Field name="duration" label="Duration" defaultValue={warranty?.duration || quotes[0]?.warranty_note || ""} /><Field name="warrantyReference" label="Warranty reference" defaultValue={warranty?.warranty_reference} /><Field name="serialNumbers" label="Serial numbers" defaultValue={warranty?.serial_numbers} /><Field name="coverage" label="Coverage" defaultValue={warranty?.coverage} /></div><Field name="terms" label="Terms" defaultValue={warranty?.terms} textarea /><button disabled={pending} className="min-h-12 rounded-[14px] bg-[var(--brand-blue)] text-sm font-bold text-white disabled:opacity-60">{pending ? "Saving..." : "Save Warranty"}</button><Feedback state={state} /></form></Card>; }
function RepairSummary({ data, totals }: { data: RepairExecutionData; totals: ReturnType<typeof labourTotals> }) { const completed = data.repair.status === "completed"; return <Card id="summary" title="Repair summary" eyebrow={completed ? "Read-only after completion" : "Structured draft"} icon="book"><div className="grid gap-4 lg:grid-cols-2"><Summary label="Original problem" value={data.repair.problem_description} /><Summary label="Diagnosis" value={data.diagnosis?.summary || "No diagnosis recorded."} /><Summary label="Work completed" value={data.checklist.filter((item) => item.completed).map((item) => item.label).join(", ") || "No completed checklist items."} /><Summary label="Parts replaced" value={data.parts.map((part) => `${part.quantity} × ${part.part_name}`).join(", ") || "No parts recorded."} /><Summary label="Testing results" value={`${data.tests.filter((item) => item.result === "pass").length} passed / ${data.tests.length || testingDefaults.length} tracked`} /><Summary label="Warranty" value={data.warranty?.warranty_provided ? `${data.warranty.duration || "Warranty"}: ${data.warranty.coverage || "Coverage not specified"}` : "No warranty record."} /><Summary label="Technician" value={data.repair.technician?.display_name || data.repair.technician?.full_name || "Not available"} /><Summary label="Completion time" value={data.repair.completed_at ? dateTime(data.repair.completed_at) : `${totals.total} labour minutes recorded`} /></div></Card>; }
function CompletionWizard({ reference, completion, confirmations }: { reference: string; completion: ReturnType<typeof completionReadiness>; confirmations: ExecutionConfirmation[] }) { const [state, action, pending] = useActionState(confirmQualityAndComplete, initial); return <Card id="completion" title="Completion workflow" eyebrow="Final quality gate" icon="check"><div className="grid gap-3 sm:grid-cols-2">{completion.items.map((item) => <div key={item.label} className={`rounded-2xl p-4 ${item.ok ? "bg-[var(--trust-green-surface)] text-[var(--trust-green)]" : "bg-red-50 text-[var(--danger)]"}`}><p className="font-bold">{item.ok ? "✓" : "•"} {item.label}</p></div>)}</div><form action={action} className="mt-5 rounded-2xl bg-[var(--secondary-surface)] p-4"><input type="hidden" name="reference" value={reference} /><label className="flex gap-3 text-sm font-bold text-[var(--deep-navy)]"><input name="qualityConfirmation" type="checkbox" className="mt-1 size-5 accent-[var(--brand-blue)]" /> I confirm that all required repair procedures have been completed.</label><button disabled={pending || !completion.allReady} className="mt-4 min-h-12 rounded-[14px] bg-[var(--deep-navy)] px-5 text-sm font-bold text-white disabled:opacity-50">{pending ? "Completing..." : "Complete Repair"}</button><Feedback state={state} /></form>{confirmations.length ? <p className="mt-4 rounded-2xl bg-[var(--trust-green-surface)] p-4 text-sm font-bold text-[var(--trust-green)]">Quality confirmed at {dateTime(confirmations[0].confirmed_at)}</p> : null}</Card>; }

function QuotationBuilder({ reference, diagnosis, quotes, parts }: { reference: string; diagnosis: ExecutionDiagnosis | null; quotes: ExecutionQuote[]; parts: ExecutionPart[] }) { const [state, action, pending] = useActionState(sendQuotation, initial); const latest = quotes[0]; const currency = latest?.currency || parts[0]?.currency || "ZAR"; return <Card id="quotation" title="Quotation builder" eyebrow="Transparent customer approval" icon="shield"><form action={action} className="grid gap-4 rounded-2xl bg-[var(--secondary-surface)] p-4"><input type="hidden" name="reference" value={reference} /><div className="grid gap-3 sm:grid-cols-3"><Field name="currency" label="Currency" defaultValue={currency} /><Field name="estimatedCompletion" label="Estimated completion" type="datetime-local" /><Field name="revisionReason" label="Revision reason" defaultValue={latest ? "Updated quotation" : "Initial quotation"} /></div><div className="grid gap-3 sm:grid-cols-3"><Field name="labour" label="Labour" type="number" /><Field name="parts" label="Replacement parts" type="number" /><Field name="serviceFee" label="Diagnostic fee" type="number" /></div><div className="grid gap-3 sm:grid-cols-4"><Field name="collectionFee" label="Collection fee" type="number" /><Field name="deliveryFee" label="Delivery fee" type="number" /><Field name="discount" label="Discount" type="number" /><Field name="tax" label="Tax optional" type="number" /></div><Field name="warranty" label="Warranty terms" defaultValue={latest?.warranty_note} textarea /><Field name="notes" label="Customer-visible quotation summary" defaultValue={diagnosis?.public_notes || diagnosis?.summary} textarea required /><button disabled={pending} className="min-h-12 rounded-[14px] bg-[var(--brand-blue)] px-5 text-sm font-bold text-white disabled:opacity-60">{pending ? "Sending..." : latest ? "Send Revised Quote" : "Create Quote"}</button><Feedback state={state} /></form><QuotationSummary quote={latest} diagnosis={diagnosis} parts={parts} /></Card>; }
function QuotationSummary({ quote, diagnosis, parts }: { quote?: ExecutionQuote; diagnosis: ExecutionDiagnosis | null; parts: ExecutionPart[] }) { if (!quote) return <Empty title="No quotation yet" body="Create a real quotation after diagnosis. No prices are estimated or fabricated." />; const rows = quote.lineItems?.length ? quote.lineItems : [{ id: "labour", quote_id: quote.id, item_type: "labour", description: "Labour", quantity: 1, unit_amount: Number(quote.labour_amount || 0), total_amount: Number(quote.labour_amount || 0) }, { id: "parts", quote_id: quote.id, item_type: "part", description: "Replacement parts", quantity: 1, unit_amount: Number(quote.parts_amount || 0), total_amount: Number(quote.parts_amount || 0) }].filter((row) => row.total_amount); return <div className="mt-5 rounded-2xl border border-[var(--divider)] p-4"><div className="flex flex-wrap items-center justify-between gap-3"><h3 className="font-bold text-[var(--deep-navy)]">Quotation v{quote.version}</h3><span className="rounded-full bg-[var(--blue-surface)] px-3 py-1 text-xs font-black text-[var(--brand-blue)]">{label(quote.status)}</span></div><dl className="mt-4 grid gap-2">{rows.map((row) => <Cost key={row.id} label={row.description} value={money(row.total_amount, quote.currency)} />)}<Cost label="Discount" value={money(quote.discount_amount ?? null, quote.currency)} /><Cost label="Tax" value={money(quote.tax_amount ?? null, quote.currency)} /><Cost label="Total" value={money(quote.total_amount, quote.currency)} strong /></dl><div className="mt-4 grid gap-3 sm:grid-cols-2"><Summary label="Repair summary" value={quote.notes || diagnosis?.public_notes || "No customer-visible summary recorded."} /><Summary label="Diagnosis summary" value={diagnosis?.summary || "Diagnosis summary not recorded."} /><Summary label="Estimated completion" value={quote.estimated_completion_at ? dateTime(quote.estimated_completion_at) : "Not provided"} /><Summary label="Parts needed" value={parts.map((part) => `${part.quantity} × ${part.part_name}`).join(", ") || "No parts recorded."} /></div></div>; }
function RepairProgress({ reference, events, current }: { reference: string; events: ExecutionEvent[]; current: string }) { const [state, action, pending] = useActionState(updateRepairProgress, initial); return <Card id="progress" title="Repair progress" eyebrow="Customer-visible updates" icon="tool"><form action={action} className="grid gap-3 rounded-2xl bg-[var(--secondary-surface)] p-4"><input type="hidden" name="reference" value={reference} /><Select name="stage" label="Progress stage" options={["diagnosis_complete", "parts_ordered", "parts_received", "repair_started", "repair_continued", "testing", "quality_check", "ready_for_collection", "completed"]} /><Field name="description" label="Customer update" textarea required /><button disabled={pending} className="min-h-12 rounded-[14px] bg-[var(--deep-navy)] text-sm font-bold text-white disabled:opacity-60">Update Progress</button><Feedback state={state} /></form><DelayDialog reference={reference} /><Timeline events={events} current={current} /></Card>; }
function DelayDialog({ reference }: { reference: string }) { const [state, action, pending] = useActionState(reportRepairDelay, initial); return <form action={action} className="mt-4 grid gap-3 rounded-2xl border border-amber-200 bg-amber-50 p-4"><input type="hidden" name="reference" value={reference} /><p className="text-sm font-black uppercase tracking-[0.14em] text-amber-700">Delay management</p><Select name="delayReason" label="Delay reason" options={["Waiting for parts", "Customer unavailable", "Additional diagnosis", "Supplier delay", "Other"]} /><Field name="delayDetails" label="Customer explanation" textarea required /><button disabled={pending} className="min-h-11 rounded-[14px] bg-amber-600 px-4 text-sm font-bold text-white disabled:opacity-60">Notify Delay</button><Feedback state={state} /></form>; }
function MessageCenter({ reference, messages, diagnosis }: { reference: string; messages: ExecutionMessage[]; diagnosis: ExecutionDiagnosis | null }) { const templates = ["Diagnosis completed.", "Parts have been ordered.", "Repair has started.", "Testing is underway.", "Your device is ready for collection."]; return <Card id="messages" title="Customer communication" eyebrow="Messages and reusable updates" icon="book"><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-5">{templates.map((item) => <span key={item} className="rounded-xl bg-[var(--blue-surface)] p-2 text-xs font-bold text-[var(--brand-blue)]">{item}</span>)}</div><div className="mt-4"><MessageForm reference={reference} /></div>{messages.length ? <div className="mt-4 grid gap-3">{messages.map((message) => <article key={message.id} className="rounded-2xl bg-[var(--secondary-surface)] p-4"><div className="flex flex-wrap justify-between gap-2"><p className="text-sm font-bold text-[var(--deep-navy)]">{label(message.sender_role)}</p><p className="text-xs text-[var(--muted-text)]">{dateTime(message.created_at)} · {message.read_at ? "Read" : "Sent"}</p></div><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-[var(--secondary-text)]">{message.message}</p></article>)}</div> : <Empty title="No customer messages" body="Repair messages, image references, document notes and system updates will appear once real communication exists." />}<div className="mt-4 grid gap-3 lg:grid-cols-3"><Note title="Customer-visible" body={diagnosis?.public_notes || "No customer-visible repair note recorded."} /><Note title="Internal technician" body={diagnosis?.private_notes || "No internal technician note recorded."} internal /><Note title="Documents" body="PDF attachments and invoices are future-ready extension points. No payment processing is implemented." internal /></div></Card>; }
function CustomerTimeline({ events, current }: { events: ExecutionEvent[]; current: string }) { const stages = ["quotation_sent", "repair_in_progress", "waiting_for_parts", "testing", "quality_check", "ready_for_collection", "completed"]; return <Card id="customer-timeline" title="Customer timeline" eyebrow="Read-only confidence path" icon="network"><ol className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{stages.map((stage) => { const event = events.find((item) => item.status === stage); const active = current === stage; return <li key={stage} className={`rounded-2xl p-4 ${active ? "bg-[var(--blue-surface)] ring-2 ring-[var(--brand-blue)]" : event ? "bg-[var(--trust-green-surface)]" : "bg-[var(--secondary-surface)]"}`}><p className="font-bold text-[var(--deep-navy)]">{label(stage)}</p><p className="mt-1 text-xs leading-5 text-[var(--secondary-text)]">{event ? dateTime(event.created_at) : "Not reached"}</p></li>; })}</ol></Card>; }
function NotificationPanel({ notifications }: { notifications: ExecutionNotification[] }) { return <Card title="Notifications" eyebrow="Customer alerts" icon="spark">{notifications.length ? <div className="grid gap-3">{notifications.map((item) => <article key={item.id} className="rounded-2xl bg-[var(--secondary-surface)] p-4"><p className="text-sm font-bold text-[var(--deep-navy)]">{item.title}</p>{item.message ? <p className="mt-1 text-sm leading-6 text-[var(--secondary-text)]">{item.message}</p> : null}<p className="mt-2 text-xs text-[var(--muted-text)]">{dateTime(item.created_at)} · {item.read_at ? "Read" : "Unread"}</p></article>)}</div> : <Empty title="No notifications" body="Quote, delay, repair and collection notifications will appear here only when real notifications are created." />}</Card>; }
function CollectionReadiness({ reference, completion, readiness }: { reference: string; completion: ReturnType<typeof completionReadiness>; readiness: ExecutionReadiness }) { const [state, action, pending] = useActionState(markReadyForCollection, initial); const checks = [["repairComplete", "Repair complete", completion.checklistComplete], ["testingPassed", "Testing passed", completion.testingPassed], ["photosUploaded", "Photos uploaded", completion.items.find((i) => i.label === "Photos uploaded")?.ok], ["summaryGenerated", "Summary generated", completion.items.find((i) => i.label === "Repair summary complete")?.ok], ["warrantyRecorded", "Warranty recorded", completion.items.find((i) => i.label === "Warranty recorded")?.ok], ["customerNotified", "Customer notified", completion.items.find((i) => i.label === "Customer notification sent")?.ok]] as const; return <Card id="collection" title="Collection readiness" eyebrow="Handover gate" icon="check"><form action={action} className="grid gap-3"><input type="hidden" name="reference" value={reference} />{checks.map(([name, title, ok]) => <label key={name} className="flex items-center gap-3 rounded-2xl bg-[var(--secondary-surface)] p-3 text-sm font-bold text-[var(--deep-navy)]"><input name={name} type="checkbox" defaultChecked={Boolean(ok)} className="size-5 accent-[var(--brand-blue)]" />{title}</label>)}<button disabled={pending} className="min-h-12 rounded-[14px] bg-[var(--trust-green)] px-5 text-sm font-bold text-white disabled:opacity-60">Mark Ready for Collection</button><Feedback state={state} /></form>{readiness?.ready_marked_at ? <p className="mt-4 rounded-2xl bg-[var(--trust-green-surface)] p-3 text-sm font-bold text-[var(--trust-green)]">Ready marked at {dateTime(readiness.ready_marked_at)}</p> : null}</Card>; }
function AuditLog({ events, quotes, messages }: { events: ExecutionEvent[]; quotes: ExecutionQuote[]; messages: ExecutionMessage[] }) { const rows = [...events.map((event) => ({ id: `e-${event.id}`, title: event.title, type: "Status", at: event.created_at })), ...quotes.map((quote) => ({ id: `q-${quote.id}`, title: `Quotation v${quote.version} ${label(quote.status)}`, type: "Quote", at: quote.created_at })), ...messages.map((message) => ({ id: `m-${message.id}`, title: `Message from ${label(message.sender_role)}`, type: "Message", at: message.created_at }))].sort((a, b) => new Date(b.at).getTime() - new Date(a.at).getTime()); return <Card id="audit" title="Audit log" eyebrow="Immutable activity record" icon="shield">{rows.length ? <div className="grid gap-2">{rows.map((row) => <div key={row.id} className="flex flex-wrap items-center justify-between gap-2 rounded-2xl bg-[var(--secondary-surface)] p-3"><p className="text-sm font-bold text-[var(--deep-navy)]">{row.title}</p><p className="text-xs text-[var(--muted-text)]">{row.type} · {dateTime(row.at)}</p></div>)}</div> : <Empty title="No audit records" body="Status changes, quote revisions, messages, uploads and completion actions will appear once created." />}</Card>; }
function DeviceSummary({ repair }: { repair: ExecutionRepair }) { return <Card title="Device summary" eyebrow="Repair context" icon="device"><dl className="grid gap-3"><Info label="Device" value={`${repair.brand} ${repair.model}`} /><Info label="Category" value={repair.device_category} /><Info label="Warranty" value={repair.warranty_status || "Not provided"} /><Info label="Age" value={repair.approximate_age || "Not provided"} /><Info label="Location" value={`${repair.area}, ${repair.city}`} /></dl></Card>; }
function CustomerPanel({ repair }: { repair: ExecutionRepair }) { return <Card title="Customer" eyebrow="Limited private information" icon="user"><Info label="Name" value={repair.customer?.display_name || repair.customer?.full_name || "Not available"} /><Info label="Phone" value={repair.customer?.phone || "Not available"} /><Info label="Service" value={label(repair.service_preference)} /></Card>; }
function Timeline({ events, current }: { events: ExecutionEvent[]; current: string }) { return <Card id="timeline" title="Timeline" eyebrow="Audit trail" icon="network">{events.length ? <ol className="grid gap-3">{events.map((event) => <li key={event.id} className={`rounded-2xl p-3 ${event.status === current ? "bg-[var(--blue-surface)]" : "bg-[var(--secondary-surface)]"}`}><p className="text-sm font-bold text-[var(--deep-navy)]">{event.title}</p><p className="mt-1 text-xs text-[var(--secondary-text)]">{dateTime(event.created_at)} · {label(event.responsible_party)}</p>{event.description ? <p className="mt-1 text-sm text-[var(--secondary-text)]">{event.description}</p> : null}</li>)}</ol> : <Empty title="No audit events" body="Status changes will appear here with timestamp and responsible party." />}</Card>; }

function Card({ id, title, eyebrow, icon, children }: { id?: string; title: string; eyebrow: string; icon: IconName; children: React.ReactNode }) { return <section id={id} className="rounded-[28px] bg-white p-5 shadow-[var(--shadow-soft)] sm:p-6"><div className="mb-5 flex items-start gap-3"><span className="grid size-11 shrink-0 place-items-center rounded-2xl bg-[var(--blue-surface)] text-[var(--brand-blue)]"><Icon name={icon} /></span><div><p className="text-xs font-black uppercase tracking-[0.16em] text-[var(--brand-blue)]">{eyebrow}</p><h2 className="mt-1 text-xl font-bold text-[var(--deep-navy)]">{title}</h2></div></div>{children}</section>; }
function Field({ name, label: fieldLabel, defaultValue, textarea = false, required = false, type = "text" }: { name: string; label: string; defaultValue?: string | null; textarea?: boolean; required?: boolean; type?: string }) { return <label className="grid gap-2 text-sm font-bold text-[var(--deep-navy)]">{fieldLabel}{textarea ? <textarea name={name} defaultValue={defaultValue || ""} required={required} rows={4} className="rounded-[14px] border border-[var(--divider)] bg-white p-4 outline-none focus:ring-2 focus:ring-[var(--brand-blue)]" /> : <input name={name} type={type} defaultValue={defaultValue || ""} required={required} className="min-h-12 rounded-[14px] border border-[var(--divider)] bg-white px-4 outline-none focus:ring-2 focus:ring-[var(--brand-blue)]" />}</label>; }
function Select({ name, label: fieldLabel, defaultValue, options }: { name: string; label: string; defaultValue?: string; options: string[] }) { return <label className="grid gap-2 text-sm font-bold text-[var(--deep-navy)]">{fieldLabel}<select name={name} defaultValue={defaultValue || options[0]} className="min-h-12 rounded-[14px] border border-[var(--divider)] bg-white px-4 capitalize outline-none focus:ring-2 focus:ring-[var(--brand-blue)]">{options.map((option) => <option key={option} value={option}>{label(option)}</option>)}</select></label>; }
function Feedback({ state }: { state: TechnicianWorkflowState }) { return state.message ? <p role={state.ok ? "status" : "alert"} className={`mt-2 rounded-xl p-2 text-xs font-bold ${state.ok ? "bg-[var(--trust-green-surface)] text-[var(--trust-green)]" : "bg-red-50 text-[var(--danger)]"}`}>{state.message}</p> : null; }
function AutosaveIndicator({ pending, state }: { pending: boolean; state: TechnicianWorkflowState }) { return <p className="rounded-xl bg-[var(--secondary-surface)] p-3 text-xs font-bold text-[var(--muted-text)]">{pending ? "Saving asynchronously..." : state.message || "Autosave-ready structured fields. Save when each section is complete."}</p>; }
function Metric({ label: metricLabel, value }: { label: string; value: string }) { return <div className="rounded-2xl bg-[var(--secondary-surface)] p-4"><dt className="text-xs font-black uppercase tracking-[0.14em] text-[var(--muted-text)]">{metricLabel}</dt><dd className="mt-2 text-sm font-bold text-[var(--deep-navy)]">{value}</dd></div>; }
function DarkMetric({ label: metricLabel, value }: { label: string; value: string }) { return <div className="rounded-2xl bg-white/10 p-3 ring-1 ring-white/10"><dt className="text-xs font-black uppercase tracking-[0.14em] text-blue-100">{metricLabel}</dt><dd className="mt-1 font-bold text-white">{value}</dd></div>; }
function Info({ label: infoLabel, value }: { label: string; value: string }) { return <div className="mb-3"><dt className="text-xs font-black uppercase tracking-[0.14em] text-[var(--muted-text)]">{infoLabel}</dt><dd className="mt-1 text-sm font-bold leading-6 text-[var(--deep-navy)]">{value}</dd></div>; }
function Note({ title, body, internal = false }: { title: string; body: string; internal?: boolean }) { return <article className={`rounded-2xl p-4 ${internal ? "bg-slate-950 text-white" : "bg-[var(--secondary-surface)]"}`}><h3 className="font-bold">{title}</h3><p className={`mt-2 whitespace-pre-wrap text-sm leading-6 ${internal ? "text-slate-200" : "text-[var(--secondary-text)]"}`}>{body}</p>{internal ? <p className="mt-2 text-xs font-bold text-amber-200">Never exposed to customers.</p> : null}</article>; }
function Summary({ label: summaryLabel, value }: { label: string; value: string }) { return <div className="rounded-2xl bg-[var(--secondary-surface)] p-4"><h3 className="font-bold text-[var(--deep-navy)]">{summaryLabel}</h3><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-[var(--secondary-text)]">{value}</p></div>; }
function Cost({ label: costLabel, value, strong = false }: { label: string; value: string; strong?: boolean }) { return <div className="flex items-center justify-between gap-4 border-b border-[var(--divider)] pb-2 last:border-0"><dt className="text-sm text-[var(--secondary-text)]">{costLabel}</dt><dd className={`text-sm ${strong ? "font-black text-[var(--deep-navy)]" : "font-semibold text-[var(--deep-navy)]"}`}>{value}</dd></div>; }
function Empty({ title, body }: { title: string; body: string }) { return <div className="mt-4 rounded-2xl bg-[var(--secondary-surface)] p-5"><p className="font-bold text-[var(--deep-navy)]">{title}</p><p className="mt-2 text-sm leading-6 text-[var(--secondary-text)]">{body}</p></div>; }
function timestamp(item?: ExecutionItem) { const value = item?.checked_at || item?.tested_at || item?.completed_at; return value ? dateTime(value) : "No timestamp"; }
function labourTotals(entries: ExecutionTime[]) { const sum = (category: string) => entries.filter((entry) => entry.category === category).reduce((total, entry) => total + Number(entry.minutes || 0), 0); const diagnosis = sum("diagnosis"); const repair = sum("repair"); const testing = sum("testing"); const paused = sum("paused"); return { diagnosis, repair, testing, paused, total: diagnosis + repair + testing - paused }; }
function completionReadiness(data: RepairExecutionData) { const checklistComplete = checklistDefaults.every((key) => data.checklist.some((item) => item.item_key === key && item.completed)); const testingPassed = testingDefaults.every((key) => data.tests.some((item) => item.item_key === key && item.result === "pass")); const items = [{ label: "Checklist complete", ok: checklistComplete }, { label: "Photos uploaded", ok: data.photos.length > 0 }, { label: "Testing passed", ok: testingPassed }, { label: "Repair summary complete", ok: Boolean(data.diagnosis?.summary) }, { label: "Warranty recorded", ok: Boolean(data.warranty) }, { label: "Customer notification sent", ok: data.events.some((event) => /notified|message|completed/i.test(`${event.title} ${event.description || ""}`)) }]; return { items, checklistComplete, testingPassed, requiredCount: items.length, readyCount: items.filter((item) => item.ok).length, allReady: items.every((item) => item.ok) }; }
function label(value: string) { return (value || "Not provided").replaceAll("_", " ").replace(/\b\w/g, (char) => char.toUpperCase()); }
function dateTime(value: string) { return new Intl.DateTimeFormat("en", { dateStyle: "medium", timeStyle: "short" }).format(new Date(value)); }
function money(value: number | null, currency = "ZAR") { return value === null || value === undefined ? "—" : new Intl.NumberFormat("en", { style: "currency", currency }).format(Number(value)); }






